def manifest_line(path):
    """the line of ConfigApp/titleshare/MANIFEST.md5 for a file of the copy (a patch changes the md5: it is read here, not written)"""
    with open(os.path.join(root, 'ConfigApp', 'titleshare', 'MANIFEST.md5')) as f:
        for line in f.read().splitlines():
            if line.endswith('  ' + path):
                return line
    raise KeyError(path)


def dist_md5(name):
    """the md5 of a delivered file. The plugin is not a file of dist/ (ONE package: it is inside the app): its numbers are those of the resource the app is built with"""
    with open(os.path.join(root, 'ConfigApp', 'data', name) if name.endswith('.3gx') else os.path.join(root, 'dist', name), 'rb') as f:
        return hashlib.md5(f.read()).hexdigest()


def flip(digest):
    """the same md5 with the last digit another one"""
    return digest[:-1] + ('0' if digest[-1] != '0' else '1')


def dotted(n):
    """a size as the documents write it: 748880 -> 748.880"""
    return '{:,}'.format(n).replace(',', '.')


