def model_rechecksum(m):
    m = bytearray(m)
    m[make_model.HASH_AT:make_model.HASH_AT + 32] = hashlib.sha256(bytes(m[:make_model.HASH_AT]) + bytes(m[make_model.HDR:])).digest()
    return bytes(m)


def model_flip_at(index):
    def flip(m):
        m = bytearray(m)
        m[index] ^= 0xFF
        return bytes(m)
    return flip


model_flip_head = model_flip_at(0x30)        # the Title ID of the header: the checksum of the model no longer fits
model_flip_code = model_flip_at(0x20000)     # a byte of the installer (its ExeFS)
model_flip_meta = model_flip_at(-1)          # the last byte of the model (its SMDH, the icon)


def model_cut(m):
    return m[:-1]


def model_placeholder(m):
    return PLACEHOLDER_MODEL


def model_layout(m):
    info = make_model.parse_model(m)
    return info, make_model.cia_layout(bytes(m[make_model.HDR:make_model.HDR + info['head']]))


def model_other_version(m):
    """a VALID model of the child of another version of 3DS Link: the TMD, the ticket and the header say the next micro (the one before when this is the last), the checksum is made again"""
    info, L = model_layout(m)
    v = info['version']
    other_v = v + 1 if (v & 15) < 15 else v - 1
    m = bytearray(m)
    struct.pack_into('>H', m, make_model.HDR + L['hb'] + 0x9C, other_v)
    struct.pack_into('>H', m, make_model.HDR + L['tb'] + 0xA6, other_v)
    struct.pack_into('<H', m, 0x10, other_v)
    return model_rechecksum(m)


def model_other_bytes(m):
    """another VALID model of the same version, as the model of another build is (makerom draws the title key of the ticket at random in every run): the app that is delivered carries the first one"""
    info, L = model_layout(m)
    m = bytearray(m)
    m[make_model.HDR + L['tb'] + 0x7F] ^= 0x55
    return model_rechecksum(m)


def picture_lost(b):
    """the delivered app without the first picture of the guide (a byte of it is wrong): what a build that forgot the pictures, or took them from another build, would deliver"""
    pic = open(os.path.join(root, 'ConfigApp', 'build', 'step1.t3x'), 'rb').read()
    return b.replace(pic, pic[:40] + bytes([pic[40] ^ 0xFF]) + pic[41:])


