def plugin_flip_mid(b):
    """the plugin resource of the tree with ONE byte different in the middle (the header, the size and the version are as they were): the app would carry another build"""
    m = bytearray(b)
    m[len(m) // 2] ^= 0x01
    return bytes(m)


def plugin_other_version(b):
    """the plugin resource of the tree whose header says another revision (the version word, bytes 8..11, is the revision in byte 9)"""
    m = bytearray(b)
    m[9] ^= 0x01
    return bytes(m)


def plugin_lost(b):
    """the delivered app with the plugin it carries changed by one byte: what an app built with the plugin before this one (or none) would deliver"""
    plugin = open(os.path.join(root, 'ConfigApp', 'data', 'AzaharLink.3gx'), 'rb').read()
    return b.replace(plugin, plugin_flip_mid(plugin))


